<?php class AdminController{
function dashboard(){requireRole('admin');$stats=['users'=>db()->query('SELECT COUNT(*) FROM users')->fetchColumn(),'activities'=>db()->query('SELECT COUNT(*) FROM activities')->fetchColumn(),'reservations'=>db()->query('SELECT COUNT(*) FROM reservations')->fetchColumn(),'revenue'=>db()->query("SELECT COALESCE(SUM(a.price),0) FROM reservations r JOIN sessions s ON s.id=r.session_id JOIN activities a ON a.id=s.activity_id WHERE r.status IN ('confirmed','completed')")->fetchColumn()];$chart=db()->query("SELECT a.title,COUNT(r.id) bookings,COALESCE(SUM(CASE WHEN r.status IN ('confirmed','completed') THEN a.price ELSE 0 END),0) revenue FROM activities a LEFT JOIN sessions s ON s.activity_id=a.id LEFT JOIN reservations r ON r.session_id=s.id GROUP BY a.id ORDER BY bookings DESC LIMIT 8")->fetchAll();view('admin/dashboard',compact('stats','chart'));}
function staff(){requireRole('admin');require_once __DIR__.'/../models/User.php';$staff=User::allStaff();view('admin/staff',compact('staff'));}
function createCoach(){requireRole('admin');check_csrf();require_once __DIR__.'/../models/User.php';try{User::createCoach($_POST);flash('success','Compte coach créé.');}catch(Throwable $e){flash('danger','Impossible de créer ce compte. Vérifiez l’adresse e-mail.');}redirect('/admin/equipe');}
function toggleCoach(){requireRole('admin');check_csrf();require_once __DIR__.'/../models/User.php';User::toggle((int)$_POST['id']);redirect('/admin/equipe');}
}